mapper.select:
SELECT i.item_id, i.category, COALESCE(i.popularity, 0) AS popularity
FROM  i WHERE category IN (
    #{category}
) ORDER BY i.popularity DESC LIMIT #{limit}

SELECT item_id, COALESCE(popularity, 0) AS popularity, category, rn FROM (
    SELECT item_id, popularity, category,
        ROW_NUMBER() OVER (PARTITION BY category ORDER BY popularity DESC) rn
    FROM  WHERE category IS NOT NULL
) t WHERE rn <= #{perCategory} ORDER BY rn ASC, t.popularity DESC LIMIT #{limit}

SELECT i.title FROM user_behavior b JOIN  i ON i.item_id=b.item_id
WHERE b.user_id=#{userId} AND b.action IN ('CLICK','LIKE','PLAY','RATING')
AND i.title IS NOT NULL ORDER BY b.ts DESC LIMIT #{limit}

SELECT b.item_id AS item_id, i.category AS category FROM user_behavior b
JOIN  i ON i.item_id=b.item_id
WHERE b.user_id=#{userId} AND b.action='RATING' AND b.value>=4 ORDER BY b.ts DESC LIMIT #{limit}

SELECT category, count(*) AS c FROM 
WHERE title ILIKE ANY (#{patterns,typeHandler=com.recsys.persistence.typehandler.TextListTypeHandler}) AND category IS NOT NULL
GROUP BY category ORDER BY c DESC LIMIT #{limit}
